// SPDX-License-Identifier: Apache-2.0
//! The datetime kernels across daylight-saving transitions in two zones
//! (America/Los_Angeles, Europe/Berlin) against Spark 4.2
//! (`tests/fixtures/spark-4.2.0/dst-transitions.json`, generated by
//! `tests/scripts/gen_dst_goldens.py`): field extraction, instant to date,
//! `+ INTERVAL` of days (a calendar day keeps the wall clock), hours
//! (elapsed time) and months, and a date's midnight.
#![forbid(unsafe_code)]

use arrow_array::types::{Date32Type, Int32Type, TimestampMicrosecondType};
use arrow_array::{Date32Array, StringArray, TimestampMicrosecondArray, cast::AsArray};
use arrow_schema::{DataType, TimeUnit};
use krishiv_kernels::cast::{CastMode, CastOptions, TimeZoneRules, cast};
use krishiv_kernels::datetime::{
    DatePart, date_add, extract_timestamp, timestamp_add_day_time, timestamp_add_months,
};
use krishiv_kernels::{KernelCtx, Operand};
use krishiv_testkit::kernel_eval::JiffZone;
use serde_json::Value;

type R = Result<(), Box<dyn std::error::Error>>;

const HOUR: i64 = 3_600_000_000;
const DAY: i64 = 24 * HOUR;

fn ltz() -> DataType {
    DataType::Timestamp(TimeUnit::Microsecond, Some("UTC".into()))
}

fn int(case: &Value, key: &str) -> Result<i64, String> {
    case[key].as_i64().ok_or_else(|| format!("no {key}"))
}

#[test]
fn kernels_match_spark_across_dst_transitions() -> R {
    let path = krishiv_testkit::tests_dir().join("fixtures/spark-4.2.0/dst-transitions.json");
    let fixture: Value = serde_json::from_str(&std::fs::read_to_string(path)?)?;
    let ctx = KernelCtx::new();
    let mut failures = Vec::new();
    let (mut instants, mut dates) = (0_usize, 0_usize);
    for case in fixture["cases"].as_array().ok_or("cases")? {
        let name = case["zone"].as_str().ok_or("zone")?;
        let zone = JiffZone::new(name).ok_or("zone")?;
        let tz: &dyn TimeZoneRules = &zone;
        let opts = CastOptions {
            mode: CastMode::Ansi,
            time_zone: tz,
        };
        let mut check = |what: &str, got: i64, want: i64| {
            if got != want {
                failures.push(format!("{name} {what} {case}: got {got}, Spark {want}"));
            }
        };
        if case["kind"] == "instant" {
            instants += 1;
            let t = TimestampMicrosecondArray::from(vec![int(case, "x")?]).with_timezone("UTC");
            let field = |part| -> Result<i64, Box<dyn std::error::Error>> {
                let out = extract_timestamp(part, &t, Some(tz))?;
                Ok(i64::from(out.as_primitive::<Int32Type>().value(0)))
            };
            check("hour", field(DatePart::Hour)?, int(case, "hour")?);
            check("minute", field(DatePart::Minute)?, int(case, "minute")?);
            check("day", field(DatePart::Day)?, int(case, "day")?);
            check("month", field(DatePart::Month)?, int(case, "month")?);
            let d = cast(&t, &DataType::Date32, &opts)?;
            let d = d.as_primitive::<Date32Type>();
            check("date", i64::from(d.value(0)), int(case, "date")?);
            let next = date_add(
                Operand::Array(d),
                Operand::<Int32Type>::Scalar(Some(1)),
                &ctx,
            )?;
            check("date_add", i64::from(next.value(0)), int(case, "date_add")?);
            let day_time = |micros: i64, negate: bool| -> Result<i64, Box<dyn std::error::Error>> {
                let out = timestamp_add_day_time(
                    Operand::Array(&t),
                    Operand::Scalar(Some(micros)),
                    negate,
                    Some(tz),
                    false,
                )?;
                Ok(out.value(0))
            };
            check("+1 day", day_time(DAY, false)?, int(case, "plus_1_day")?);
            check("-1 day", day_time(DAY, true)?, int(case, "minus_1_day")?);
            check(
                "+24 hours",
                day_time(DAY, false)?,
                int(case, "plus_24_hours")?,
            );
            check("+1 hour", day_time(HOUR, false)?, int(case, "plus_1_hour")?);
            let months = |m: i32| -> Result<i64, Box<dyn std::error::Error>> {
                let out = timestamp_add_months(
                    Operand::Array(&t),
                    Operand::Scalar(Some(m)),
                    false,
                    Some(tz),
                    false,
                )?;
                Ok(out.value(0))
            };
            check("+1 month", months(1)?, int(case, "plus_1_month")?);
            check("+1 year", months(12)?, int(case, "plus_1_year")?);
        } else {
            dates += 1;
            let s = StringArray::from(vec![case["s"].as_str().ok_or("s")?]);
            let d = cast(&s, &DataType::Date32, &opts)?;
            let d: &Date32Array = d.as_primitive::<Date32Type>();
            let midnight = cast(d, &ltz(), &opts)?;
            let t: &TimestampMicrosecondArray = midnight.as_primitive::<TimestampMicrosecondType>();
            check("to_timestamp", t.value(0), int(case, "to_timestamp")?);
            let add = |micros: i64, negate: bool| -> Result<i64, Box<dyn std::error::Error>> {
                let out = timestamp_add_day_time(
                    Operand::Array(t),
                    Operand::Scalar(Some(micros)),
                    negate,
                    Some(tz),
                    false,
                )?;
                Ok(out.value(0))
            };
            check(
                "+36 hours",
                add(36 * HOUR, false)?,
                int(case, "plus_36_hours")?,
            );
            check("+24 hours", add(DAY, false)?, int(case, "plus_24_hours")?);
            check("-1 hour", add(HOUR, true)?, int(case, "minus_1_hour")?);
        }
    }
    assert!(
        failures.is_empty(),
        "{} differences, first: {:#?}",
        failures.len(),
        &failures[..failures.len().min(20)]
    );
    assert!(
        instants > 100 && dates > 10,
        "{instants} instants, {dates} dates"
    );
    Ok(())
}
